import re,collections
rows=[]
for l in t.split('\n'):
    m=re.match(r'Date: (.+?) \|\| User: (\d+) \|\| Instance: (.*)',l)
    if m: rows.append(m.groups())
c=collections.Counter(r[1] for r in rows);print(len(rows),len(c),c.most_common(5))

